            foreach ($headings as $heading) {
                $values[] = $row->value($heading);
            }
            $rows[] = new ResultRow($values);
        }

        $columns = [];
        foreach ($headings as $index => $heading) {
            $columns[] = new ResultColumn($heading, self::typeOf($rows, $index));
        }

        return new self($columns, $rows);
    }

