     *     $diagram = new \App\Reporter\Diagram\Diagram();
     *     $edge = new \App\Gql\Datum\EdgeDatum('e', ['calls'], [], 'a', 'b');
     *     \App\Reporter\Query\ResultElements::collectRelations($diagram, new \App\Gql\Result\ResultRow([$edge]));
